import numpy as np
import matplotlib.pyplot as plt

# Load the results
results = np.load('Result_HR_P_sys_P_dia_exercise_20_from_steady.npy', allow_pickle=True)

X = np.load('X_samples_HR_P_sys_P_dia_exercise_20_from_steady.npy', allow_pickle=True)

# Organize into a dict: param → {"LOW": (..), "HIGH": (..)}
param_data = {}
for label, values in results:
    param_name, level = label.split()
    if param_name not in param_data:
        param_data[param_name] = {}
    param_data[param_name][level] = values

# Compute absolute differences for each variable
diffs_hr = {}
diffs_sys = {}
diffs_dia = {}

for param, levels in param_data.items():
    if "LOW" in levels and "HIGH" in levels:
        low_vals = np.array(levels["LOW"])
        high_vals = np.array(levels["HIGH"])
        diff = np.abs(high_vals - low_vals)

        diffs_hr[param] = diff[0]
        diffs_sys[param] = diff[1]
        diffs_dia[param] = diff[2]
    else:
        print(f"Warning: missing HIGH/LOW for {param}")

# Sort by descending difference
sorted_params_hr = sorted(diffs_hr, key=diffs_hr.get, reverse=True)
sorted_params_sys = sorted(diffs_sys, key=diffs_sys.get, reverse=True)
sorted_params_dia = sorted(diffs_dia, key=diffs_dia.get, reverse=True)

# Plot function
def plot_diffs_split(sorted_keys, diffs_dict, title_base, ylabel, color):
    n = len(sorted_keys)
    half = n // 2

    # First half
    keys_1 = sorted_keys[:half]
    values_1 = [diffs_dict[k] for k in keys_1]

    plt.figure(figsize=(8, 5))
    plt.bar(keys_1, values_1, color=color)
    plt.title(f"{title_base} (Part 1)")
    plt.ylabel(ylabel)
    plt.xticks(rotation=90)
    plt.grid(axis='y')
    plt.tight_layout()
    plt.show()

    # Second half
    keys_2 = sorted_keys[half:]
    values_2 = [diffs_dict[k] for k in keys_2]

    plt.figure(figsize=(8, 5))
    plt.bar(keys_2, values_2, color=color)
    plt.title(f"{title_base} (Part 2)")
    plt.ylabel(ylabel)
    plt.xticks(rotation=90)
    plt.grid(axis='y')
    plt.tight_layout()
    plt.show()

# Plot all three
plot_diffs_split(sorted_params_hr, diffs_hr, "Heart Rate Differences (HIGH - LOW)", "ΔHR", "red")
plot_diffs_split(sorted_params_sys, diffs_sys, "Systolic Pressure Differences (HIGH - LOW)", "ΔP_sys", "blue")
plot_diffs_split(sorted_params_dia, diffs_dia, "Diastolic Pressure Differences (HIGH - LOW)", "ΔP_dia", "green")


